// ---------- physics ----------
let RAPIER = null, world = null;
const bodies = {};
const dyn = [];
async function initPhysics() {
  const mod = RAPIER_MODULE;
  RAPIER = mod.default || mod;
  await RAPIER.init();
  world = new RAPIER.World({ x: 0, y: -9.81, z: 0 });
  world.timestep = 1 / 60;
  const gb = world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
  world.createCollider(RAPIER.ColliderDesc.trimesh(tpos, tidx).setFriction(0.9).setRestitution(0.5), gb);
  for (const t of TREES) world.createCollider(RAPIER.ColliderDesc.cylinder(1.5, 0.28).setTranslation(t.x, H(t.x, t.z) + 1.4, t.z), gb);
  for (const r of ROCKS) world.createCollider(RAPIER.ColliderDesc.ball(r.r * 0.8).setTranslation(r.x, H(r.x, r.z) + r.r * 0.3, r.z), gb);
  for (const l of LOGS) { const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(0, l.a, Math.PI / 2)); world.createCollider(RAPIER.ColliderDesc.capsule(l.len / 2 - 0.2, 0.23).setTranslation(l.x, H(l.x, l.z) + 0.2, l.z).setRotation(q), gb); }
  for (let i = 0; i < 44; i++) { const a = (i + 0.5) / 44 * Math.PI * 2, x = Math.cos(a) * (FENCE_R + 0.05), z = Math.sin(a) * (FENCE_R + 0.05); const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(0, -a, 0)); world.createCollider(RAPIER.ColliderDesc.cuboid(0.06, 0.8, 1.05).setTranslation(x, H(x, z) + 0.6, z).setRotation(q), gb); }
  world.createCollider(RAPIER.ColliderDesc.cylinder(0.05, 0.22).setTranslation(BOWL.x, H(BOWL.x, BOWL.z) + 0.05, BOWL.z), gb);
  bodies.human = world.createRigidBody(RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(PORCH.x, H(PORCH.x, PORCH.z) + 0.9, PORCH.z));
  world.createCollider(RAPIER.ColliderDesc.capsule(0.6, 0.2), bodies.human);
  // dog kinematic body
  bodies.dog = world.createRigidBody(RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(0, 0.4, 2));
  world.createCollider(RAPIER.ColliderDesc.capsule(0.22, 0.13).setRotation({ x: Math.SQRT1_2, y: 0, z: 0, w: Math.SQRT1_2 }), bodies.dog);
  $('chipPhys').textContent = 'rapier ' + (RAPIER.version ? RAPIER.version() : 'ok'); $('chipPhys').classList.add('on');
}
function makeDynamic(name, mesh, colDesc, pos, opts = {}) {
  const rb = world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(pos.x, pos.y, pos.z).setCcdEnabled(true).setLinearDamping(opts.lin ?? 0.15).setAngularDamping(opts.ang ?? 0.6));
  world.createCollider(colDesc.setRestitution(opts.rest ?? 0.3).setFriction(opts.fric ?? 0.7).setDensity(opts.dens ?? 300), rb);
  const o = { name, mesh, rb, held: false, prevVy: 0, lastSpeed: 0 };
  dyn.push(o); scene.add(mesh); mesh.castShadow = true; return o;
}
let ball, bone, treats = [];
const crates = [];
function initProps() {
  const bm = new THREE.Mesh(new THREE.SphereGeometry(0.045, 20, 14), M('#d9f04e', { roughness: 0.95 }));
  ball = makeDynamic('ball', bm, RAPIER.ColliderDesc.ball(0.045), V3(1.2, H(1.2, 4) + 0.3, 4), { rest: 0.72, dens: 160, lin: 0.3, ang: 2.2 });
  const bg = new THREE.Group();
  const bmat = M('#f3ead8', { roughness: 0.6 });
  addMesh(new THREE.CapsuleGeometry(0.025, 0.18, 4, 8), bmat, 0, 0, 0, bg).rotation.z = Math.PI / 2;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) addMesh(new THREE.SphereGeometry(0.035, 10, 8), bmat, sx * 0.12, 0, sz * 0.025, bg);
  bone = makeDynamic('bone', bg, RAPIER.ColliderDesc.capsule(0.1, 0.035).setRotation({ x: 0, y: 0, z: Math.SQRT1_2, w: Math.SQRT1_2 }), V3(-2.5, H(-2.5, 0.5) + 0.3, 0.5), { rest: 0.2, dens: 400 });
  const cmat = M('#e2c79b');
  for (const [x, z] of [[3.5, -1], [-3, -1.6], [6.2, 1.2]]) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.32, 0.32), cmat);
    crates.push(makeDynamic('crate', m, RAPIER.ColliderDesc.cuboid(0.16, 0.16, 0.16), V3(x, H(x, z) + 0.4, z), { rest: 0.1, dens: 60, fric: 0.8 }));
  }
}
function spawnTreat(p, v) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.025, 0.035), M('#8a5530'));
  const t = makeDynamic('treat', m, RAPIER.ColliderDesc.cuboid(0.025, 0.0125, 0.0175), p, { rest: 0.2, dens: 500 });
  t.rb.setLinvel(v, true); treats.push(t); return t;
}
function removeDyn(o) { world.removeRigidBody(o.rb); scene.remove(o.mesh); dyn.splice(dyn.indexOf(o), 1); treats = treats.filter(t => t !== o); }
const bodyPos = o => { const t = o.rb.translation(); return V3(t.x, t.y, t.z); };
const bodyVel = o => { const t = o.rb.linvel(); return V3(t.x, t.y, t.z); };
function setHeld(o, held) {
  o.held = held;
  o.rb.setBodyType(held ? RAPIER.RigidBodyType.KinematicPositionBased : RAPIER.RigidBodyType.Dynamic, true);
}


// ---- yard/io/audio.js
// ---------- audio ----------
let actx = null, audioOK = false;
addEventListener('pointerdown', () => { audioOK = true; }, { capture: true });
addEventListener('keydown', () => { audioOK = true; }, { capture: true });
function audio() { if (!$('sound').checked || !audioOK) return null; if (!actx) { try { actx = new AudioContext(); } catch (e) { return null; } } if (actx.state === 'suspended') actx.resume(); return actx; }
function distGain(p) { return clamp(1.6 / (0.6 + camera.position.distanceTo(p) * 0.25), 0.05, 1); }
function bark(p, pitch = 1, n = 1) {
  if (typeof brain !== 'undefined' && p && dog.root && p.distanceTo(dog.root.position) < 1) brain.barkT = now;
  const a = audio(); if (!a) return; const g0 = distGain(p);
  for (let k = 0; k < n; k++) {
    const t = a.currentTime + k * 0.22;
    const o = a.createOscillator(); o.type = 'sawtooth';
    o.frequency.setValueAtTime(520 * pitch, t); o.frequency.exponentialRampToValueAtTime(260 * pitch, t + 0.13);
    const nz = a.createBufferSource(); const buf = a.createBuffer(1, a.sampleRate * 0.15, a.sampleRate); const d = buf.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1; nz.buffer = buf;
    const f1 = a.createBiquadFilter(); f1.type = 'bandpass'; f1.frequency.value = 900 * pitch; f1.Q.value = 2.5;
    const f2 = a.createBiquadFilter(); f2.type = 'bandpass'; f2.frequency.value = 2200 * pitch; f2.Q.value = 3;
    const g = a.createGain(); g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.5 * g0, t + 0.012); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.16);
    const gn = a.createGain(); gn.gain.value = 0.35;
    o.connect(f1); o.connect(f2); nz.connect(gn); gn.connect(f1); f1.connect(g); f2.connect(g); g.connect(a.destination);
    o.start(t); o.stop(t + 0.18); nz.start(t); nz.stop(t + 0.15);
  }
}
function whine(p) { const a = audio(); if (!a) return; const t = a.currentTime; const o = a.createOscillator(); o.type = 'sine'; o.frequency.setValueAtTime(900, t); o.frequency.linearRampToValueAtTime(1400, t + 0.3); o.frequency.linearRampToValueAtTime(800, t + 0.7); const g = a.createGain(); g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(0.12 * distGain(p), t + 0.08); g.gain.linearRampToValueAtTime(0.0001, t + 0.75); o.connect(g); g.connect(a.destination); o.start(t); o.stop(t + 0.8); }
function thud(p, v) { const a = audio(); if (!a) return; const t = a.currentTime; const o = a.createOscillator(); o.frequency.setValueAtTime(180, t); o.frequency.exponentialRampToValueAtTime(60, t + 0.08); const g = a.createGain(); g.gain.setValueAtTime(clamp(v * 0.08, 0, 0.35) * distGain(p), t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.1); o.connect(g); g.connect(a.destination); o.start(t); o.stop(t + 0.12); }
let pantT = 0;
function pant(p) { const a = audio(); if (!a) return; const t = a.currentTime; const nz = a.createBufferSource(); const buf = a.createBuffer(1, a.sampleRate * 0.14, a.sampleRate); const d = buf.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.sin(Math.PI * i / d.length); nz.buffer = buf; const f = a.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 1500; f.Q.value = 0.8; const g = a.createGain(); g.gain.value = 0.05 * distGain(p); nz.connect(f); f.connect(g); g.connect(a.destination); nz.start(t); }


// ---- yard/dog/setup.js
// ---------- the dog body ----------
const dog = {
  root: new THREE.Group(), pivot: new THREE.Group(), ready: false,
  pos: V3(0, 0, 2), yaw: Math.PI, v: 0, w: 0, S: 0.47, yaw0: 0,
  bones: {}, rest: new Map(), legs: [], mesh: null, mat: null,
  noseL: V3(), mouthL: V3(), eyeL: V3(), fwdM: V3(), upM: V3(0, 1, 0),
  posture: { sit: 0, down: 0, bow: 0, reach: 0 }, postureT: { sit: 0, down: 0, bow: 0, reach: 0 },
  phase: 0, gaitW: [1, 0, 0], freq: 0, duty: 0.65, act: 0, standing: true,
  head: { yaw: 0, pitch: 0, roll: 0, tYaw: 0, tPitch: 0, tRoll: 0 },
  tailPhase: 0, earPerk: 0, bodyPitch: 0, heat: 0, hop: 0, pawLift: 0
};
scene.add(dog.root); dog.root.add(dog.pivot);
const QY = a => new THREE.Quaternion().setFromAxisAngle(V3(0, 1, 0), a);
let QC = QY(0), QCi = QY(0);
const dqE = new THREE.Euler();
function dq(pitch, yaw, roll, out = new THREE.Quaternion()) { dqE.set(pitch, yaw, roll, 'YXZ'); out.setFromEuler(dqE); return out.premultiply(QC).multiply(QCi); }

const LEGDEF = [
  { id: 'LF', up: 'frontUpr.L', mid: 'frontLeg.L_03', end: 'frontHorselink.L', toe: ['frontToe.L'], front: true, side: 1 },
  { id: 'RF', up: 'frontUpr.R', mid: 'frontLeg.R_03', end: 'frontHorselink.R', toe: ['frontToe.R'], front: true, side: -1 },
  { id: 'LH', up: 'rearUpr.L', mid: 'rearLwr.L', end: 'rearHorselink.L', toe: ['rearFoot.L', 'rearToe.L'], front: false, side: 1 },
  { id: 'RH', up: 'rearUpr.R', mid: 'rearLwr.R', end: 'rearHorselink.R', toe: ['rearFoot.R', 'rearToe.R'], front: false, side: -1 }
];
const bk = n => n.replace(/[\[\]\.:\/]/g, '').replace(/\s/g, '_').toLowerCase();
const NEED = ['root', 'hips', 'spine2', 'spine_03', 'chest', 'neck1', 'head', 'tail1', 'tail3', 'tail_03'];

function setupDog(gltf, label) {
  // clear previous
  while (dog.pivot.children.length) dog.pivot.remove(dog.pivot.children[0]);
  dog.bones = {}; dog.rest.clear(); dog.legs = []; dog.ready = false;
  const root = gltf.scene;
  let mesh = null;
  root.traverse(o => { if (o.isSkinnedMesh && !mesh) mesh = o; if (o.isBone) dog.bones[bk(o.name)] = o; });
  const raw = dog.bones; dog.bones = new Proxy(raw, { get: (t, k) => t[bk(String(k))] });
  const miss = [...NEED, ...LEGDEF.flatMap(l => [l.up, l.mid, l.end, ...l.toe])].filter(n => !dog.bones[n]);
  if (!mesh || miss.length) { toast('rig not recognised: missing ' + (mesh ? miss.slice(0, 3).join(', ') : 'skinned mesh')); return false; }
  dog.mesh = mesh;
  mesh.frustumCulled = false; mesh.castShadow = true; mesh.receiveShadow = true;
  const mat = mesh.material; mat.metalness = 0; mat.side = THREE.FrontSide; dog.mat = mat;
  root.updateMatrixWorld(true);
  const W = n => dog.bones[n].getWorldPosition(V3());
  const head = W('head'), tail = W('tail1');
  const f = V3(head.x - tail.x, 0, head.z - tail.z).normalize();
  dog.yaw0 = Math.atan2(f.x, f.z); dog.fwdM.copy(f);
  QC = QY(dog.yaw0); QCi = QY(-dog.yaw0);
  // skinned bind pose vertices in model space (quantized GLBs fold scale into the bind matrices)
  const pa = mesh.geometry.attributes.position; const bb = new THREE.Box3();
  const sk = mesh.geometry.attributes.skinIndex, sw = mesh.geometry.attributes.skinWeight;
  const headIdx = mesh.skeleton.bones.indexOf(dog.bones['head']);
  const verts = [];
  mesh.skeleton.update();
  for (let i = 0; i < pa.count; i += 3) {
    const p = mesh.getVertexPosition(i, V3()).applyMatrix4(mesh.matrixWorld);
    bb.expandByPoint(p);
    let hw = 0; if (sk) for (let k = 0; k < 4; k++) if (sk.getComponent(i, k) === headIdx) hw += sw.getComponent(i, k);
    if (hw > 0.5) verts.push(p);
  }
  const height = bb.max.y - bb.min.y;
  dog.S = 0.78 / height;
  const center = W('clavicle.L').add(W('clavicle.R')).add(W('rearUpr.L')).add(W('rearUpr.R')).multiplyScalar(0.25);
  dog.pivot.rotation.set(0, -dog.yaw0, 0);
  dog.pivot.scale.setScalar(dog.S);
  const c = center.clone().applyAxisAngle(V3(0, 1, 0), -dog.yaw0).multiplyScalar(dog.S);
  dog.pivot.position.set(-c.x, -bb.min.y * dog.S, -c.z);
  dog.pivot.add(root);
  root.traverse(o => { if (o.isBone) dog.rest.set(o, { p: o.position.clone(), q: o.quaternion.clone(), s: o.scale.clone() }); });
  // nose, mouth, eyes from vertices near the head
  const hb = head;
  let best = -1e9; const nose = hb.clone().addScaledVector(f, 0.3);
  for (const v of verts) { const pr = v.x * f.x + v.z * f.z; if (pr > best) { best = pr; nose.copy(v); } }
  dog.noseL.copy(nose).sub(hb);
  dog.mouthL.copy(hb).lerp(nose, 0.82).sub(hb); dog.mouthL.y -= 0.07;
  dog.eyeL.copy(hb).lerp(nose, 0.35).sub(hb); dog.eyeL.y += 0.07;
  // legs
  dog.root.position.set(0, 0, 0); dog.root.rotation.set(0, 0, 0); dog.root.updateMatrixWorld(true);
  for (const L of LEGDEF) {
    const b = { up: dog.bones[L.up], mid: dog.bones[L.mid], end: dog.bones[L.end] };
    const A = b.up.getWorldPosition(V3()), B = b.mid.getWorldPosition(V3()), C = b.end.getWorldPosition(V3());
    const toeBone = dog.bones[L.toe[L.toe.length - 1]]; const T = toeBone.getWorldPosition(V3());
    const pawL = V3(); for (const n of L.toe) pawL.add(dog.bones[n].position);
    const ac = C.clone().sub(A).normalize(); const pole = B.clone().sub(A); pole.sub(ac.clone().multiplyScalar(pole.dot(ac))).normalize();
    dog.legs.push(Object.assign({}, L, b, {
      l1: A.distanceTo(B), l2: B.distanceTo(C), pawL, pole,
      nom: V3(T.x, 0, T.z), toeH: Math.max(T.y, 0.005), hipL: A.clone(),
      foot: V3(), lift: V3(), land: V3(), stance: true, swingS: 0, ph: 0, step: null, trail: []
    }));
  }
  dog.frontZ = (dog.legs[0].nom.z + dog.legs[1].nom.z) / 2; dog.rearZ = (dog.legs[2].nom.z + dog.legs[3].nom.z) / 2;
  dog.halfW = (dog.legs[0].nom.x - dog.legs[1].nom.x) / 2;
  dog.rootL = dog.bones['root'].getWorldPosition(V3());
  // tongue
  const tongue = new THREE.Mesh(new THREE.SphereGeometry(0.06, 10, 8), M('#f07aa6', { roughness: 0.5 }));
  tongue.scale.set(0.55, 0.18, 1.2); dog.bones['head'].add(tongue); tongue.position.copy(dog.mouthL).add(V3(0, -0.02, 0)); tongue.visible = false; dog.tongue = tongue;
  // place feet
  dog.root.position.set(dog.pos.x, H(dog.pos.x, dog.pos.z), dog.pos.z); dog.root.rotation.y = dog.yaw; dog.root.updateMatrixWorld(true);
  for (const l of dog.legs) { l.foot.copy(nomWorld(l, dog.pos, dog.yaw)); l.stance = true; }
  dog.phase = 0;
  dog.ready = true;
  const tris = mesh.geometry.index ? mesh.geometry.index.count / 3 : pa.count / 3;
  $('mdlName').textContent = label;
  $('mdlInfo').innerHTML = `<b>bones</b><span>${mesh.skeleton.bones.length}</span><b>triangles</b><span>${Math.round(tris).toLocaleString()}</span><b>scale</b><span>${dog.S.toFixed(3)} m per unit</span><b>shoulder</b><span>${(dog.legs[0].hipL.y).toFixed(2)} m</span><b>facing fix</b><span>${(dog.yaw0 * 180 / Math.PI).toFixed(1)} deg</span><b>stand height</b><span>${(height * dog.S).toFixed(2)} m</span>`;
  if (skel) { scene.remove(skel); skel = null; }
  orgSetup();
  return true;
}
function nomWorld(l, pos, yaw, out = V3()) {
  const P = dog.postureOff ? dog.postureOff[l.id] : null;
  let x = l.nom.x, z = l.nom.z; if (P) { x += P.x; z += P.z; }
  const c = Math.cos(yaw), s = Math.sin(yaw);
  out.set(pos.x + c * x + s * z, 0, pos.z - s * x + c * z);
  out.y = H(out.x, out.z) + l.toeH; return out;
}
function resetPose() { for (const [b, r] of dog.rest) { b.position.copy(r.p); b.quaternion.copy(r.q); b.scale.copy(r.s); } }


// ---- yard/dog/body.js
// gait tables, order LF RF LH RH (Hildebrand style phase offsets). Pace pairs same side legs, canter is three beat.
const GAITS = [
  { name: 'walk', off: [0.25, 0.75, 0.0, 0.5], duty: 0.64, clr: 0.045 },
  { name: 'pace', off: [0.0, 0.5, 0.0, 0.5], duty: 0.5, clr: 0.055 },
  { name: 'trot', off: [0.0, 0.5, 0.5, 0.0], duty: 0.42, clr: 0.07 },
  { name: 'canter', off: [0.3, 0.55, 0.0, 0.3], duty: 0.38, clr: 0.08 },
  { name: 'gallop', off: [0.62, 0.5, 0.0, 0.12], duty: 0.32, clr: 0.09 }
];
const ikA = V3(), ikB = V3(), ikC = V3(), ikT = V3();
function rotateBoneWorld(bone, qd) {
  bone.getWorldQuaternion(tmpQ[0]); tmpQ[0].premultiply(qd);
  bone.parent.getWorldQuaternion(tmpQ[1]).invert();
  bone.quaternion.copy(tmpQ[1].multiply(tmpQ[0]));
  bone.updateMatrixWorld(true);
}
function setBoneWorldQuat(bone, qw) { bone.parent.getWorldQuaternion(tmpQ[1]).invert(); bone.quaternion.copy(tmpQ[1].multiply(qw)); bone.updateMatrixWorld(true); }
function solveLeg(l, target, endTilt) {
  const qEnd = tmpQ[2].copy(dog.root.quaternion).multiply(endTilt).multiply(dog.pivot.quaternion);
  const paw = tmpV[5].copy(l.pawL).multiplyScalar(dog.S).applyQuaternion(qEnd);
  ikT.copy(target).sub(paw);
  l.up.getWorldPosition(ikA); l.mid.getWorldPosition(ikB); l.end.getWorldPosition(ikC);
  const l1 = l.l1, l2 = l.l2;
  const dv = tmpV[6].copy(ikT).sub(ikA); let d = dv.length();
  const dn = dv.clone().divideScalar(d || 1);
  d = clamp(d, Math.abs(l1 - l2) + 1e-3, l1 + l2 - 1e-3);
  const pole = tmpV[7].copy(l.pole).applyQuaternion(dog.root.quaternion);
  pole.sub(dn.clone().multiplyScalar(pole.dot(dn))).normalize();
  const a = (l1 * l1 - l2 * l2 + d * d) / (2 * d), h = Math.sqrt(Math.max(l1 * l1 - a * a, 0));
  const Bn = ikA.clone().addScaledVector(dn, a).addScaledVector(pole, h);
  const Cn = ikA.clone().addScaledVector(dn, d);
  rotateBoneWorld(l.up, tmpQ[3].setFromUnitVectors(ikB.clone().sub(ikA).normalize(), Bn.clone().sub(ikA).normalize()));
  l.mid.getWorldPosition(ikB); l.end.getWorldPosition(ikC);
  rotateBoneWorld(l.mid, tmpQ[3].setFromUnitVectors(ikC.clone().sub(ikB).normalize(), Cn.clone().sub(ikB).normalize()));
  setBoneWorldQuat(l.end, qEnd);
}

// ---------- locomotion ----------
