  if (dog.mat) { const want = xr ? 0.35 : 1; if ((dog.mat.opacity !== want)) { dog.mat.transparent = xr; dog.mat.opacity = want; dog.mat.depthWrite = !xr; dog.mat.needsUpdate = true; } }
